CLAUSES = [[1, -2], [-1, 3], [2, 3]]   # 1..3 号变量，负数表示取反


def sat(n, m, clauses):
    """给定的赋值 m（第 i 位是变量 i+1）是否满足全部子句"""
    for c in clauses:
        if not any(((m >> (abs(l) - 1)) & 1) == (1 if l > 0 else 0) for l in c):
            return False
    return True


models = [m for m in range(1 << 3) if sat(3, m, CLAUSES)]
print("model count =", len(models))
print("first model =", format(models[0], "03b") if models else "UNSAT")

